import numpy as np
def _sig(values):
    arr = np.asarray(values, dtype=float)
    logs = np.log(np.abs(arr.ravel()) + 1.0e-300)
    weight = 1.0 + 0.5 * np.cos(0.7 * np.arange(logs.size))
    return float(arr.shape[0] + np.sum(weight * logs))
def table_for(tops, n, curvature, cubic, shift):
    t, _ = np.polynomial.legendre.leggauss(n)
    rows = []
    for top, c2, c3, c0 in zip(tops, curvature, cubic, shift):
        half = 0.5 * (top - 0.5)
        x = np.concatenate(([top], half * t + 0.5 + half))
        rows.append(c2 * (x - 1.1) ** 2 - c3 * (x - 1.1) ** 3 + c0)
    return np.array(rows)
tab = table_for([1.6, 1.7], 40, [600.0, 500.0], [700.0, 450.0], [0.0, 0.0])
assert np.allclose(_sig(compute_bond_scission_rates(tab.copy(), np.array([1.6, 1.7]), np.array([1.18e12, 1.67e12]))), target)

